head.script:
scwin.checkDataSel = function() {
	var arr = select1.itemArr,
		bool1,
		bool2;
	(arr.length) ? bool1 = true: bool1 = false;
	(arr[0].label == 'label_test1' && arr[1].label == 'label_test2') ?
	bool2 = true: bool2 = false;
	return bool1 && bool2;
};
scwin.onpageload = function() {
	dlt_code.setJSON([{
		"cls_cd": "O0003",
		"detl_cd": "test1",
		"detl_cd_nm": "label_test1"
	}, {
		"cls_cd": "O0003",
		"detl_cd": "test2",
		"detl_cd_nm": "label_test2"
	}, {
		"cls_cd": "O0004",
		"detl_cd": "test4",
		"detl_cd_nm": "label_test4"
	}]);
	// selectbox 가 바인딩한 linkedDataList 를 화면 로드 뒤에 생성
	$p.data.create({
		"id": "ldt_code_O0003",
		"type": "linkedDataList",
		"option": {
			"valueAttribute": "",
			"bind": "dlt_code",
			"filterCondition": "cls_cd == 'O0003'",
			"sortCondition": ""
		}
	});
};
